import { PDFDocument } from 'pdf-lib';
import JSZip from 'jszip';
import type { ReportFileValidator, FileRequest } from '../../application/report-files/job-ports';
import { ReportFileError } from '../../application/report-files/service';
import { sniffKind } from '../../domain/files/mime-sniff';
import { inspectZipForBomb } from '../../domain/files/zip-inspect';
import { UPLOAD_LIMITS } from '../../domain/files/upload-limits';
/** Structural validation of generated bytes, never a file generator. */
export class ReportGeneratedFileValidator implements ReportFileValidator {
  async validate(format: FileRequest['format'], bytes: Uint8Array): Promise<void> {
    try {
      if (!bytes.byteLength || bytes.byteLength > 30 * 1024 * 1024) throw new Error();
      if (format === 'pdf') {
        if (sniffKind(bytes) !== 'pdf') throw new Error();
        const pdf = await PDFDocument.load(bytes);
        if (!pdf.getPageCount()) throw new Error();
        return;
      }
      if (sniffKind(bytes) !== 'zip') throw new Error();
      const inspected = await inspectZipForBomb(bytes, { maxEntries: UPLOAD_LIMITS.maxZipEntries,
        maxDecompressedBytes: UPLOAD_LIMITS.maxDecompressedBytes, maxNestingDepth: UPLOAD_LIMITS.maxZipNestingDepth });
      if (!inspected.ok) throw new Error();
      const zip = await JSZip.loadAsync(bytes);
      const part = format === 'docx' ? 'word/document.xml' : 'ppt/presentation.xml';
      const types = await zip.file('[Content_Types].xml')?.async('string');
      const document = await zip.file(part)?.async('string');
      if (!types || !document || /<!DOCTYPE|<!ENTITY/i.test(types + document)) throw new Error();
      if (format === 'docx') {
        if (!types.includes('wordprocessingml.document.main+xml') || !/<w:body[\s>]/.test(document)) throw new Error();
      } else {
        if (!types.includes('presentationml.presentation.main+xml') || !/<p:sldId[\s>]/.test(document)
          || !Object.keys(zip.files).some(path => /^ppt\/slides\/slide[0-9]+\.xml$/.test(path))) throw new Error();
      }
    } catch { throw new ReportFileError('INVALID_FILE'); }
  }
}
